// The LOGS workspace, AS GRAPH SOURCE (#3646, epic #3604). Transcribed from the live feature file: the
// runtime loader compiles this and mounts it, resolving every import to the app's real modules (the
// shared/ui design system + the store via appModules, the audit derivation via the logs graph-platform,
// and the sibling tab bodies as sibling records). Behaviour runs here — no forked render path.
//
// ONE SCREEN FOR EVERY HISTORY THE APP KEEPS (epic-a-unified-logs-workspace). The `bsc logs` engine
// (#1607) already carries eight streams — audit · skill · mcp · hook · coord · activity · done · perm —
// plus the `sessions` / `waiting` / `cost` rollups, and almost none of it was reachable from the UI. This
// is a SURFACE over something already built, which is why it starts with one real tab rather than seven
// stubs: Sessions, Waiting, Skills, Hooks, Cost and Streams each land as their own slice.
//
// WHERE THIS SCREEN CAME FROM. It was the Security workspace, which held four tabs. Three were deleted
// (retire-agentprofile-and-strip-security-to-activity) and are not coming back:
//
//   Profiles     — it edited an `AgentProfile` while CALLING it a "role" ("New role", "Delete role"),
//                  which is the duplication the persona floor replaced. Capability is authored with
//                  `bsc persona`, by the architect, and READ on the Teams panel. No CRUD in the UI.
//   Assignments  — it mapped a pane to a profile. With no profile authoring surface there is nothing
//                  to assign; launch resolves a pane's capability from its persona floor.
//   Flow         — it rendered "which sessions are parked on a dependency (#199)". That mechanism was
//                  REMOVED in #1039: the emitter it advertised no longer exists, there is no coordinator
//                  auto-wake, and `dependsOn` is a planning-time hint. So the view could only ever be
//                  empty, and #4174 already caught its empty state naming that removed command — which
//                  is why THIS comment does not spell it either: `logsRecordContent.test.ts` sweeps every
//                  packaged record for the literal, because a record IS the screen. The live question
//                  Flow reached for — WHO IS STUCK — is answered by `bsc logs waiting`, fed by
//                  `bsc-wait`, and becomes the Waiting tab here. Do not rebuild Flow.
//
// Activity is the one that survived, because it has a real feed behind it — and it is history, which is
// what this workspace is for.
//
// The `AgentProfile` MODEL is deliberately still wired: `buildSecurityPayload` ships it to
// mobile-studio-code over the tunnel against a byte-exact fixture, and CLAUDE.md requires coordinated
// PRs in both repos for a protocol break. Retiring it is `retire-the-agentprofile-model-behind-the-tunnel-contract`.
// The audit feed still resolves each row's decision from profile ∪ role, so those store reads stay.
import { useMemo, useState } from "react";
import { usePoll } from "@/shared/hooks/usePoll";
import {
  logsTail, logsWaiting, logsSessions, logsCosts,
  type WaitingRow, type SessionRollupRow, type CostRow,
} from "@/shared/lib/core/logsBridge";
import { type TabItem } from "@/shared/ui/layouts/TabBar";
import { Screen } from "@/shared/ui/layouts/Screen";
import { usePageTabs } from "@/shared/hooks/usePageTabs";
import { useScreenDescriptor } from "@/shared/hooks/useScreenDescriptor";
// Through the BARREL, not a deep path (#1545): the fleet dashboard is still glance-owned code, and
// re-homing its 16 modules is `the-fleet-dashboard-is-logs-owned`, filed separately.
import { FleetGraphHost } from "@/features/glance";
import { APP_ROLES } from "@/shared/lib/security/agentProfiles";
import { deriveConsoles } from "@/shared/lib/security/consoleModel";
import {
  buildAuditRows, auditDecisionCounts, type AuditDisplayRow, type DecFilter,
} from "@/features/logs/lib/auditRows";
import { useAppStore } from "@/store";
import { ActivityTab } from "@/features/logs/ActivityTab";
import { WaitingTab } from "@/features/logs/WaitingTab";
import { SkillsTab } from "@/features/logs/SkillsTab";
import { SessionsTab, type SessionSort } from "@/features/logs/SessionsTab";
import { CostTab } from "@/features/logs/CostTab";
import { StreamsTab } from "@/features/logs/StreamsTab";
import { AutomationsTab, parseAutomationLog, type AutomationRunRow } from "@/features/logs/AutomationsTab";
import { safeInvoke, fireInvoke } from "@/shared/lib/core/safeInvoke";
import { parseSkillLog, aggregateSkillTelemetry, type SkillStats } from "@/features/skills";

/** The Waiting tab's kind filter. Mirrors the four `bsc logs waiting` kinds plus `all`. */
type WaitKind = "all" | "wait" | "ask" | "request" | "permission";

/** One parsed skill-log line — the `SkillUsageRecord` shape from the telemetry module. */
interface SkillRecord { ts: string; pane: string; event: string; skill: string }

/** One managed stream on disk — the `LogFileInfo` shape. camelCase on the wire (that struct DOES
 *  carry `serde(rename_all)`, unlike `SessionRow` and `Cost`). */
interface LogFileInfo {
  stream: string; label: string; path: string;
  sizeBytes: number; mtimeMs: number; exists: boolean; text: boolean;
}

export function LogsWorkspace({ pageOverride }: { pageOverride?: string } = {}) {
  const [actDecision, setActDecision] = useState<DecFilter>("all");
  const [actConsole, setActConsole] = useState("all");
  const [waitKind, setWaitKind] = useState<WaitKind>("all");

  // Read-only: these feed the audit derivation and the row's profile chip, nothing edits them here.
  const profiles = useAppStore((s) => s.agentProfiles);
  const tabs = useAppStore((s) => s.tabs);
  const paneNames = useAppStore((s) => s.paneNames);
  const disabledPanes = useAppStore((s) => s.disabledPanes);
  const paneProfiles = useAppStore((s) => s.paneProfiles);
  const activeRepoName = useAppStore((s) => s.activeRepoName);

  // Live console/pane model derived from the real workspace tabs (see shared/lib/security/consoleModel).
  const consoles = useMemo(
    () => deriveConsoles({ tabs, paneNames, disabledPanes, paneProfiles, activeRepoName }),
    [tabs, paneNames, disabledPanes, paneProfiles, activeRepoName],
  );

  // Activity audit (#257): load the real per-pane tool log and derive each decision
  // from the pane's resolved gate (profile ∪ role) — the same rules the launch gate
  // applies. Refreshed while the Activity tab is open.
  const paneRoles = useAppStore((s) => s.paneRoles);
  const [auditRows, setAuditRows] = useState<AuditDisplayRow[]>([]);
  const [waitRows, setWaitRows] = useState<WaitingRow[]>([]);
  const [skillRecords, setSkillRecords] = useState<SkillRecord[]>([]);
  const [skillStats, setSkillStats] = useState<Record<string, SkillStats>>({});
  const [skillsLoaded, setSkillsLoaded] = useState(false);
  const [sessionRows, setSessionRows] = useState<SessionRollupRow[]>([]);
  const [sessionSort, setSessionSort] = useState<SessionSort>("activity");
  const [hideDormant, setHideDormant] = useState(false);
  const [sessionsLoaded, setSessionsLoaded] = useState(false);
  const [costRows, setCostRows] = useState<CostRow[]>([]);
  const [costLoaded, setCostLoaded] = useState(false);
  const [logFiles, setLogFiles] = useState<LogFileInfo[]>([]);
  const [filesLoaded, setFilesLoaded] = useState(false);
  const [openStream, setOpenStream] = useState<string | null>(null);
  const [streamLines, setStreamLines] = useState<string[]>([]);
  const [streamSearch, setStreamSearch] = useState("");
  const [streamLevel, setStreamLevel] = useState("all");
  const [autoRows, setAutoRows] = useState<AutomationRunRow[]>([]);
  const [autoLoaded, setAutoLoaded] = useState(false);
  const logConfig = useAppStore((s) => s.logConfig);
  const setLogConfig = useAppStore((s) => s.setLogConfig);

  const logDefs: TabItem[] = useMemo(() => [
    { id: "activity", label: "Activity", count: auditRows.length, hint: "· tool attempts" },
    { id: "waiting", label: "Waiting", count: waitRows.length, hint: "· blocked on a person" },
    { id: "skills", label: "Skills", count: skillRecords.length, hint: "· invocations" },
    { id: "sessions", label: "Sessions", count: sessionRows.length, hint: "· every stream, per session" },
    { id: "cost", label: "Cost", count: costRows.length, hint: "· token economics" },
    { id: "automations", label: "Automations", count: autoRows.length, hint: "· schedule fires" },
    { id: "streams", label: "Streams", count: logFiles.length, hint: "· the raw files" },
    // The FLEET dashboard, moved here from Glance (`the-fleet-page-belongs-to-logs`): health, lessons,
    // cost/energy and worker detail are Logs' subject — `crates/logs` is the unified log/perf/COST
    // engine — and moving it left Glance as exactly one tab per network plus the all-projects lens.
    // No `count`: it is a dashboard over live state, not a row list, so a number would be inventing one.
    { id: "fleet", label: "Fleet", hint: "· agents · throughput" },
  ], [auditRows.length, waitRows.length, skillRecords.length, sessionRows.length, costRows.length, autoRows.length, logFiles.length]);
  const { tabs: logTabs, activeId, select, reorder, tearOff } = usePageTabs("logs", logDefs);
  const tab = pageOverride ?? activeId; // active section

  usePoll(async (isCancelled) => {
    if (tab !== "activity") return;
    const lines = await logsTail("audit", 300);
    const rows = buildAuditRows(lines, { consoles, profiles, paneProfiles, paneRoles });
    if (!isCancelled()) setAuditRows(rows);
  }, 3000, [tab, paneProfiles, profiles, paneRoles, consoles]);

  // The queue is polled only while its tab is open, like the audit feed above. It reads TWO logs
  // (coord + activity) and re-derives every open/close pair from the whole file, so it is not a
  // cheap read to run in the background for a tab nobody is looking at.
  usePoll(async (isCancelled) => {
    if (tab !== "waiting") return;
    const rows = await logsWaiting();
    if (!isCancelled()) setWaitRows(rows);
  }, 3000, [tab]);

  // The skill log, parsed and aggregated by the SAME functions the library page used — one
  // derivation, so the two surfaces can never disagree about how many times a skill ran.
  // `skillsLoaded` separates "still reading" from "genuinely nothing", which matters because the
  // tab makes a CLAIM about the fleet in the empty case and must not make it before reading.
  usePoll(async (isCancelled) => {
    if (tab !== "skills") return;
    const lines = await logsTail("skill", 4000);
    if (isCancelled()) return;
    // Newest-first for the feed: `logsTail` returns newest-first unless `oldest` is passed, and
    // `parseSkillLog` preserves order, so no re-sort is needed (or wanted — a re-sort on a 4000-line
    // read is pure cost).
    const recs = parseSkillLog((lines ?? []).join("\n"));
    setSkillRecords(recs);
    setSkillStats(aggregateSkillTelemetry(recs, new Date()));
    setSkillsLoaded(true);
  }, 5000, [tab]);

  // The HEAVIEST read in the app: five streams plus the cost rollup, which re-reads every transcript
  // named in tokens.log. Polled only while its tab is open, and slower than the others for that
  // reason — a per-session rollup does not change meaningfully inside 8 seconds.
  usePoll(async (isCancelled) => {
    if (tab !== "sessions") return;
    const rows = await logsSessions();
    if (isCancelled()) return;
    setSessionRows(rows);
    setSessionsLoaded(true);
  }, 8000, [tab]);

  // Same transcript re-read as the sessions rollup, and just as slow — but a separate poll, because
  // only one of the two tabs is ever open. Sharing one would make whichever tab is showing pay for
  // the other.
  usePoll(async (isCancelled) => {
    if (tab !== "cost") return;
    const rows = await logsCosts();
    if (isCancelled()) return;
    setCostRows(rows);
    setCostLoaded(true);
  }, 8000, [tab]);

  // Schedule fires. The scheduler reads this same stream to decide what is due, so this tab and
  // the runtime cannot disagree about whether something ran.
  usePoll(async (isCancelled) => {
    if (tab !== "automations") return;
    const lines = await logsTail("automation", 2000);
    if (isCancelled()) return;
    setAutoRows(parseAutomationLog(lines ?? []));
    setAutoLoaded(true);
  }, 5000, [tab]);

  // The inventory is a stat() per file, not a read — cheap, so it refreshes faster than the
  // rollups. `openStream` is a dependency because clearing a stream has to redraw its size.
  usePoll(async (isCancelled) => {
    if (tab !== "streams") return;
    const files = await safeInvoke<LogFileInfo[]>("list_log_files", undefined, []);
    if (isCancelled()) return;
    setLogFiles(files);
    setFilesLoaded(true);
  }, 4000, [tab, openStream]);

  // The raw tail of whichever stream is open. Bounded at 500 lines, as the Settings viewer was:
  // audit.log alone is 19k lines and rendering it whole would freeze the pane.
  usePoll(async (isCancelled) => {
    if (tab !== "streams" || !openStream) return;
    const lines = await safeInvoke<string[]>("read_log_tail", { stream: openStream, limit: 500 }, []);
    if (!isCancelled()) setStreamLines(lines);
  }, 4000, [tab, openStream]);

  // The row chip's colour lookup — application roles are singletons, user profiles are stored.
  const find = (id: string) => [...APP_ROLES, ...profiles].find((p) => p.id === id);

  const { allow, ask, block } = auditDecisionCounts(auditRows);

  // WHAT `bsc app go` CAN SELECT HERE (`the-shared-navigation-mechanism-drill-select-and-show`): on the
  // Streams page, the stream files — opening one is the same two setters the row click runs. The other
  // pages are reports with nothing to open, so they publish no `select` and a select there is an error.
  useScreenDescriptor({
    workspace: "logs",
    page: tab,
    layer: tab,
    drill: [],
    selection: tab === "streams" ? openStream : null,
    targets: tab === "streams" ? logFiles.map((f) => ({ id: f.stream, label: f.label, drillable: false, selectable: true })) : [],
    select: tab === "streams" ? (id) => { setOpenStream(id); setStreamLines([]); } : undefined,
  });

  return (
    <Screen
      tabs={logTabs}
      active={tab}
      onSelect={select}
      onReorder={reorder}
      onTearOff={tearOff}
      pageOverride={pageOverride}
      className="logs-page"
      bodyClassName="body"
    >
      {tab === "activity" && (
        <ActivityTab
          rows={auditRows} consoles={consoles}
          actDecision={actDecision} setActDecision={setActDecision}
          actConsole={actConsole} setActConsole={setActConsole}
          allow={allow} ask={ask} block={block} find={find}
        />
      )}
      {tab === "waiting" && (
        <WaitingTab rows={waitRows} kind={waitKind} setKind={setWaitKind} now={Date.now()} />
      )}
      {tab === "skills" && (
        <SkillsTab records={skillRecords} stats={skillStats} loaded={skillsLoaded} />
      )}
      {tab === "sessions" && (
        <SessionsTab
          rows={sessionRows} sort={sessionSort} setSort={setSessionSort}
          hideDormant={hideDormant} setHideDormant={setHideDormant} loaded={sessionsLoaded}
        />
      )}
      {tab === "cost" && (
        <CostTab rows={costRows} loaded={costLoaded} />
      )}
      {tab === "automations" && (
        <AutomationsTab rows={autoRows} loaded={autoLoaded} now={Date.now()} />
      )}
      {tab === "streams" && (
        <StreamsTab
          files={logFiles} loaded={filesLoaded} now={Date.now()}
          caps={logConfig} setCaps={setLogConfig}
          onEnforce={() => fireInvoke("enforce_log_caps")}
          onClear={(stream) => {
            // `perf` is a SQLite store, not a text log, and has its own clear command.
            fireInvoke(stream === "perf" ? "perf_clear_history" : "clear_log", stream === "perf" ? undefined : { stream });
            if (openStream === stream) setStreamLines([]);
          }}
          selected={openStream} onSelect={(s) => { setOpenStream(s); setStreamLines([]); }}
          lines={streamLines}
          search={streamSearch} setSearch={setStreamSearch}
          level={streamLevel} setLevel={setStreamLevel}
        />
      )}
      {/* The FLEET dashboard. `FleetGraphHost` brings its own layout and its own data polling, so it
          mounts whole rather than being threaded through this page's row state. */}
      {tab === "fleet" && <FleetGraphHost />}
    </Screen>
  );
}
